"retour": "json", "security_definer": true, "volatilite": "v"}, "music_confirmer_paiement(text,text,text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "c068c4b58b530697e542298f37b6fd9d", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_creer_commande(uuid,text,text,text,text,text,text,text,date)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "83c40dd7650edc099ed25cfbe3408c9b", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_regenerer_lien_questionnaire(text,text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "05799621ad6f596efb09c5e463721bbf", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_resoudre_jeton_questionnaire(text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "7b07d0852e4a185986748bb8fc7c944c", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "s"}, "music_revoquer_lien_questionnaire(text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "59e659ec6b6767c71f2bae0feed224db", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}}, "index": {"music_order_contacts": ["music_order_contacts_pkey:unique=true"], "music_orders": ["music_orders_cle_idempotence_key:unique=true", "music_orders_jeton_questionnaire_hash_key:unique=true", "music_orders_pkey:unique=true", "music_orders_reference_key:unique=true"]}, "policies": 0, "privileges_hors_proprietaire": {"music_order_contacts": [], "music_order_ref_seq": [], "music_orders": []}, "proprietaires": {"music_order_contacts": "postgres", "music_order_ref_seq": "postgres", "music_orders": "postgres"}, "rls": {"music_order_contacts": true, "music_orders": true}, "sequences": {"music_order_ref_seq": {"cycle": false, "debut": 5, "max": 99999, "min": 5, "pas": 1, "type": "integer"}}, "tables_presentes": ["music_order_contacts", "music_orders"], "triggers": 0}'::jsonb as e),
     reel as (
    select jsonb_build_object(
      'tables_presentes', (select coalesce(jsonb_agg(relname order by relname), '[]') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname = any(array['music_orders','music_order_contacts']::text[])),
      'proprietaires', (select coalesce(jsonb_object_agg(relname, pg_get_userbyid(relowner)), '{}') from pg_class where relnamespace = 'public'::regnamespace and relname = any(array['music_orders','music_order_contacts']::text[] || array['music_order_ref_seq']::text[])),
      'colonnes', (select coalesce(jsonb_object_agg(c.relname, (select jsonb_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text order by a.attnum) from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped)), '{}')
                   from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_orders','music_order_contacts']::text[])),
      'contraintes', (select coalesce(jsonb_object_agg(c.relname, (select jsonb_agg(k.conname || ':' || k.contype::text || case when k.contype = 'f' then ':' || k.confrelid::regclass::text || ':ondelete=' || k.confdeltype::text else '' end order by k.conname) from pg_constraint k where k.conrelid = c.oid and k.contype <> 'n')), '{}')
                      from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_orders','music_order_contacts']::text[])),
      'index', (select coalesce(jsonb_object_agg(c.relname, (select coalesce(jsonb_agg(i.indexrelid::regclass::text || ':unique=' || i.indisunique::text order by i.indexrelid::regclass::text), '[]') from pg_index i where i.indrelid = c.oid)), '{}')
                from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_orders','music_order_contacts']::text[])),
      'rls', (select coalesce(jsonb_object_agg(relname, relrowsecurity), '{}') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname = any(array['music_orders','music_order_contacts']::text[])),
      'policies', (select count(*) from pg_policies where schemaname = 'public' and tablename = any(array['music_orders','music_order_contacts']::text[])),
      'triggers', (select count(*) from pg_trigger t join pg_class c on c.oid = t.tgrelid where not t.tgisinternal and c.relnamespace = 'public'::regnamespace and c.relname = any(array['music_orders','music_order_contacts']::text[])),
      'privileges_hors_proprietaire', (select coalesce(jsonb_object_agg(c.relname, (select coalesce(jsonb_agg(distinct case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end || ':' || x.privilege_type), '[]') from aclexplode(c.relacl) x where x.grantee <> c.relowner)), '{}')
                                       from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname = any(array['music_orders','music_order_contacts']::text[] || array['music_order_ref_seq']::text[])),
      'sequences', (select coalesce(jsonb_object_agg(s.sequencename, jsonb_build_object('type', s.data_type::text, 'debut', s.start_value, 'min', s.min_value, 'max', s.max_value, 'pas', s.increment_by, 'cycle', s.cycle)), '{}') from pg_sequences s where s.schemaname = 'public' and s.sequencename = any(array['music_order_ref_seq']::text[])),
      'fonctions', (select coalesce(jsonb_object_agg(p.oid::regprocedure::text, jsonb_build_object(
                       'md5_corps', md5(p.prosrc), 'security_definer', p.prosecdef, 'config', to_jsonb(p.proconfig), 'volatilite', p.provolatile::text,
                       'retour', format_type(p.prorettype, null), 'proprietaire', pg_get_userbyid(p.proowner),
                       'execute', (select coalesce(jsonb_agg(case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end order by case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end), '[]') from aclexplode(p.proacl) x where x.privilege_type = 'EXECUTE' and x.grantee <> p.proowner))), '{}')
                    from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any(array['music_creer_commande','music_confirmer_paiement','music_regenerer_lien_questionnaire','music_revoquer_lien_questionnaire','music_resoudre_jeton_questionnaire','music_annuler_commande']::text[]))
    ) as r)
select jsonb_pretty(jsonb_build_object(
  'migration', '020',
  'conforme', (select r from reel) = (select e from attendu),
  'sections_differentes', (select coalesce(jsonb_agg(k), '[]') from jsonb_object_keys((select e from attendu)) k where (select e from attendu)->k is distinct from (select r from reel)->k),
      'tables_vides', (select count(*) = 0 from public.music_orders) and (select count(*) = 0 from public.music_order_contacts),
      'sequence_intacte', (select last_value = 5 and not is_called from public.music_order_ref_seq),
      'sequence_rattachee_a_reference', (select d.refobjid = 'public.music_orders'::regclass from pg_depend d where d.objid = 'public.music_order_ref_seq'::regclass and d.deptype = 'a'),
      'statuts_futurs_prevus', (select pg_get_constraintdef(oid) like '%QUESTIONNAIRE_REÇU%' and pg_get_constraintdef(oid) like '%BRIEF_À_VALIDER%' and pg_get_constraintdef(oid) like '%BRIEF_VALIDÉ%' from pg_constraint where conname = 'music_orders_statut_valide'),
      'user_id_nullable_restrict', (select not a.attnotnull from pg_attribute a where a.attrelid = 'public.music_orders'::regclass and a.attname = 'user_id') and exists (select 1 from pg_constraint where conrelid = 'public.music_orders'::regclass and contype = 'f' and confrelid = 'auth.users'::regclass and confdeltype = 'r'),
      'sonde_lien_inconnu', public.music_resoudre_jeton_questionnaire(repeat('0', 64))->>'error' = 'LIEN_INVALIDE',
      'sonde_crm_seul_refuse', public.music_resoudre_jeton_questionnaire('CRM-00005')->>'error' = 'LIEN_INVALIDE'
)) as postcheck_020;
